import { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import axiosInstance from '../axiosConfig';

// STS-13: Organizer Views Participants — Organizer (or Admin) can see who has
// registered for a tournament they own.
const TournamentParticipants = () => {
  const { id } = useParams();
  const { user } = useAuth();
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const fetchParticipants = async () => {
      try {
        const response = await axiosInstance.get(`/api/tournaments/${id}/participants`, {
          headers: { Authorization: `Bearer ${user.token}` },
        });
        setData(response.data);
      } catch (err) {
        setError(err.response?.data?.message || 'Failed to load participants.');
      } finally {
        setLoading(false);
      }
    };

    if (user) fetchParticipants();
  }, [id, user]);

  if (loading) return <div className="text-center mt-20">Loading...</div>;
  if (error) return <div className="text-center mt-20 text-red-600">{error}</div>;

  return (
    <div className="container mx-auto p-6">
      <Link to="/my-tournaments" className="text-sm text-blue-600 underline">
        &larr; Back to My Tournaments
      </Link>
      <h1 className="text-3xl font-bold mt-2 mb-1">{data.tournamentName}</h1>
      <p className="text-gray-500 mb-6">
        {data.participants.length}/{data.maxCapacity} registered
      </p>

      {data.participants.length === 0 ? (
        <p className="text-gray-500">No one has joined this tournament yet.</p>
      ) : (
        <div className="bg-white shadow rounded divide-y">
          {data.participants.map((p) => (
            <div key={p._id} className="p-4 flex justify-between">
              <span className="font-medium">{p.name}</span>
              <span className="text-gray-500 text-sm">{p.email}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default TournamentParticipants;
